void ControlBar::updateContextStructureInventory()
{
	Object *source = m_currentSelectedDrawable->getObject();
	Player *localPlayer = ThePlayerList->getLocalPlayer();
	if (source->isLocallyControlled() == false && localPlayer->getRelationship(source->getTeam()) != (Relationship)1) {
		Drawable *draw = source->getDrawable();
		if (draw) {
			GameMessage *msg = TheMessageStream->appendMessage(GameMessage::MSG_REMOVE_FROM_SELECTED_GROUP);
			msg->appendObjectIDArgument(source->getID());
			TheInGameUI->deselectDrawable(draw);
		}
		return;
	}
	ContainModuleInterface *contain = source->getContain();
	if (!contain)
		return;
	if (m_lastRecordedInventoryCount != contain->getCount(false))
		populateStructureInventory(source, false);
}

